    private int currentStep;

    // Personal Info state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";

    // Work History state
    private List<WorkEntryViewModel> workEntries = [];

    // References state
    private List<ReferenceViewModel> references = [];

    // Cover Letter state
    private string coverLetter = "";

    private void NavigateToStep(int step)
    {
        if (step >= 0 && step < stepNames.Count)
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0) currentStep--;
    }

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        personalFullName = info.FullName;
        personalEmail = info.Email;
        personalPhone = info.Phone;
        personalAddress = info.Address;
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryViewModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceViewModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private PersonalInfo GetPersonalInfo() =>
        new(personalFullName, personalEmail, personalPhone, personalAddress);

    private List<WorkEntry> GetWorkEntries() =>
        workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList();

    private List<Reference> GetReferences() =>
        references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            GetPersonalInfo(),
            new WorkHistory(GetWorkEntries()),
            GetReferences(),
            coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}
